  "tool": "set_targeted_ops_spend",
  "arguments": {
    "by_group": {
      "E1": 300
    },
    "by_plan": {
      "A": 200
    },
    "by_group_plan": {
      "E2": {
        "B": 100
      }
    },
    "by_customer": {
      "42": 50
    }
  }
}
