arguments.cmd:
/bin/bash -c "./novamind-operation python-c \"import json,novamind_api as nm; rows=nm.query(\\\"SELECT day,tool_name,setting_type,settings_json FROM config_overrides WHERE day>=119 ORDER BY id\\\")['rows'];
for r in rows:
 s=json.loads(r['settings_json']); print('\\\\nDAY',r['day'],r['tool_name']);
 if r['setting_type']=='targeted_ad_spend': print(' ads_total',sum(v for x in s['targeted_spend'].values() for v in x.values()),json.dumps(s['targeted_spend']))
 elif r['setting_type']=='targeted_dev_spend': print(' dev_total',sum(s['targeted_spend'].values()))
 elif r['setting_type']=='promotion': print(json.dumps(s['by_group_plan']))
 else: print(json.dumps(s))\""

