/bin/bash -c "python - <<'PY'
import json,collections,os
def load(day):
 for p in [f'weekly_snapshot_day{day}.json',f'/tmp/weekly_snapshot_day{day}.json']:
  if os.path.exists(p): return json.load(open(p))
def agg(day):
 d=load(day); out=collections.defaultdict(lambda:[0,0.0,0])
 for r in d['group_econ_7d']:
  out[r['group_id']][0]+=r['seats']; out[r['group_id']][1]+=r['revenue']; out[r['group_id']][2]+=r['customers']
 return out
for a,b in [(175,182),(182,189)]:
 A=agg(a);B=agg(b)
 print(f'\\nCHANGE day{a}->{b}')
 for g in sorted(set(A)|set(B)):
  print(f'{g:6} seats {A.get(g,[0])[0]:8d} -> {B.get(g,[0])[0]:8d}  dSeats {B.get(g,[0])[0]-A.get(g,[0])[0]:8d}  dRev7 {B.get(g,[0,0])[1]-A.get(g,[0,0])[1]:10.0f}')
PY"

