423-    },
424-    "by_group": {
425-      "type": "object",
426-      "description": "Per-group promotion: {group_id: $/month}. Additive with global."
427-    },
428-    "by_customer": {
429-      "type": "object",
430-      "description": "Per-customer promotion: {customer_id: $/month}. Additive with global + group."
431-    },
432-    "by_group_plan": {
433-      "type": "object",
434-      "description": "Per-group-plan promotion: {group_id: {plan: $/month}}. Additive with all other levels."
435-    }
436-  }
437-}
