arguments.cmd:
/bin/bash -c "./novamind-operation python-c 'import re,json,collections,novamind_api as nm
rows=nm.query(\"SELECT c.group_id,t.message_text,t.seat_count,t.day FROM enterprise_turns t JOIN customers c ON c.customer_id=t.customer_id WHERE t.thread_type=\\\"new_lead\\\" AND t.sender=\\\"system\\\" AND t.close_reason=\\\"accepted\\\" AND t.day>=133\") [\"rows\"]
d=collections.defaultdict(list)
pat=re.compile(r\"\\"'$([0-9.]+)/seat.*?'"\\((?:Plan )?([ABC])\\)\")
for r in rows:
 m=pat.search(r[\"message_text\"] or \"\")
 if m: d[r[\"group_id\"]].append((float(m.group(1)),m.group(2),r[\"seat_count\"]))
out={}
for g,v in sorted(d.items()):
 seats=sum(x[2] for x in v); out[g]={\"n\":len(v),\"seats\":seats,\"avg_accept_price\":round(sum(x[0]*x[2] for x in v)/max(1,seats),2),\"min\":min(x[0] for x in v),\"max\":max(x[0] for x in v),\"plans\":dict(collections.Counter(x[1] for x in v))}
print(json.dumps(out,indent=2))'"

