{
  "/workspace/run-ceobench/week37_config.py": {
    "type": "add",
    "content": "import json

import novamind_api as nm


EXPECTED_DAY = 252

day = int(nm.vars.current_day)
if day != EXPECTED_DAY:
    raise RuntimeError(f"expected day {EXPECTED_DAY}, got {day}")

targeted_ads = {
    "content_marketing": {
        "D_S10": 30000.0,
    },
}

targeted_dev = {
    "S2": 0.0,
    "S3": 0.0,
    "D_S02": 0.0,
    "D_S07": 0.0,
    "D_S09": 0.0,
    "D_S10": 0.0,
}


def show(name, value):
    print(name)
    print(json.dumps(value, indent=2, default=str), flush=True)
    if isinstance(value, dict) and value.get("success") is False:
        raise RuntimeError(f"{name} failed: {value}")


show("ads", nm.marketing.set_targeted_ad_spend(targeted_ads))
show("targeted_dev", nm.analytics.set_targeted_dev_spend(
    targeted_spend=targeted_dev))

for tier in (1, 3, 4):
    show(f"research_tier_{tier}", nm.research.start_research_project(tier))
"
  }
}

