/bin/bash -c "./novamind-operation query \"SELECT t.thread_id,t.customer_id,t.thread_type,t.turn_number,t.sender,t.message_text,t.offer_json,t.day,t.seat_count,t.closed,t.close_reason,c.group_id FROM enterprise_turns t JOIN customers c ON c.customer_id=t.customer_id WHERE t.day BETWEEN 260 AND 266 ORDER BY t.thread_id,t.turn_number,t.message_id\" > enterprise_turns_260_266.json && python3 - <<'PY'
import json,collections,re,statistics
rows=json.load(open('enterprise_turns_260_266.json'))['rows']
by=collections.defaultdict(list)
for r in rows: by[r['thread_id']].append(r)
acc=collections.defaultdict(list); timeout=collections.defaultdict(list); closed_n=collections.Counter()
for tid,rs in by.items():
 g=rs[0]['group_id']; typ=rs[0]['thread_type']
 last=rs[-1]
 if last['closed']:
  closed_n[(g,typ,last['close_reason'])]+=1
  if last['close_reason']=='accepted':
   for r in reversed(rs):
    if r['sender']=='customer' and 'Accepted:' in (r['message_text'] or ''):
     m=re.search(r'\\"'$([0-9.]+)/seat'"',r['message_text'])
     if m: acc[(g,typ)].append((float(m.group(1)),r['seat_count'],tid))
     break
print('OUTCOME COUNTS')
for k,n in sorted(closed_n.items()): print(n,k)
print('\\nACCEPTED')
for k,v in sorted(acc.items()):
 prices=[x[0] for x in v]; print(k,'n',len(v),'seats',sum(x[1] for x in v),'avg',round(statistics.mean(prices),2),'min',min(prices),'max',max(prices))
PY"

