        "type": "object",
        "properties": {
          "customer_id": {
            "type": "integer",
            "description": "Enterprise customer ID"
          }

        },
        "required": [
          "customer_id"
        ]
      }
    }
  },
  "required": [
    "deals"
  ]
}
```

