 q=f'''SELECT s.customer_id,s.plan,s.seat_count,ROUND(s.effective_price,2) price,ROUND(s.effective_price*100.0/{wtp[g]},1) pct_wtp FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id WHERE s.status=\\\"subscribed\\\" AND c.customer_type=\\\"large\\\" AND c.group_id=\\\"{g}\\\" AND NOT EXISTS (SELECT 1 FROM enterprise_turns t WHERE t.customer_id=s.customer_id AND t.closed=0) ORDER BY pct_wtp ASC, s.seat_count DESC LIMIT 8'''; out[g]=nm.query(q)['rows']
print(json.dumps(out,indent=2,default=str))\""

