{
  "tool": "set_lead_promotion",
  "arguments": {
    "global_promotion": 5.0,
    "by_channel": {
      "linkedin": 10.0
    },
    "by_channel_group": {
      "social_media": {
        "S1": 8.0
      }
    }
  }
}
```

