import json

import novamind_api as nm


EXPECTED_DAY = 329

day = int(nm.vars.current_day)
if day != EXPECTED_DAY:
    raise RuntimeError(f"expected day {EXPECTED_DAY}, got {day}")


def show(name, value):
    print(name, flush=True)
    print(json.dumps(value, indent=2, default=str), flush=True)
    if isinstance(value, dict) and value.get("success") is False:
        raise RuntimeError(f"{name} failed: {value}")


# S2 paid leads converted at ~11.4% (organic ~11.9%) for a ~$60 blended CAC.
# Scale that line while retaining the efficient D_S09 search test. Stop D_S02
# referral and D_S10 content, whose recent CAC/payback is materially worse.
show("targeted_ads", nm.marketing.set_targeted_ad_spend({
    "content_marketing": {
        "S2": 50000.0,
    },
    "search_ads": {
        "D_S09": 6000.0,
    },
}))

# The deeper first-month D_S07 and S3 tests produced zero wins; restore their
# prior lead terms rather than carrying an ineffective discount.
show("lead_promotions", nm.marketing.set_lead_promotion(
    by_group={
        "S1": 5.0,
        "S2": 30.0,
        "S3": 10.0,
        "D_S01": 10.0,
        "D_S02": 10.0,
        "D_S03": 5.0,
        "D_S04": 20.0,
        "D_S05": 15.0,
        "D_S06": 10.0,
        "D_S07": 10.0,
        "D_S08": 10.0,
        "D_S09": 10.0,
        "D_S10": 10.0,
    },
    by_channel_group={
        "content_marketing": {"D_S10": 5.0, "S1": 10.0},
        "referral_program": {"D_S01": 15.0, "D_S07": 10.0, "S3": 25.0},
    },
))

