import json
import statistics

import novamind_api as nm


QUERY = """
WITH latest AS (
    SELECT t.* FROM enterprise_turns t
    WHERE t.message_id = (
        SELECT MAX(message_id) FROM enterprise_turns x
        WHERE x.thread_id = t.thread_id
    )
), first_system AS (
    SELECT thread_id, message_id, day, seat_count
    FROM enterprise_turns t
    WHERE sender = 'system' AND message_id = (
        SELECT MIN(message_id) FROM enterprise_turns x
        WHERE x.thread_id = t.thread_id
    )
), agent_offer AS (
    SELECT t.thread_id, t.message_id, t.day, t.offer_json
    FROM enterprise_turns t
    WHERE t.sender = 'agent' AND t.message_id = (
        SELECT MAX(message_id) FROM enterprise_turns x
        WHERE x.thread_id = t.thread_id AND x.sender = 'agent'
    )
)
SELECT l.thread_id, l.customer_id, l.thread_type, l.day AS latest_day,
       l.sender AS latest_sender, l.closed, l.close_reason,
       ao.day AS offer_day, ao.offer_json,
       fs.day AS opened_day, fs.seat_count AS opened_seats,
       c.group_id,
       s.plan AS prior_plan, s.effective_price AS prior_price,
       s.start_day AS prior_start, s.end_day AS prior_end
FROM latest l
JOIN customers c ON c.customer_id = l.customer_id
LEFT JOIN first_system fs ON fs.thread_id = l.thread_id
LEFT JOIN agent_offer ao ON ao.thread_id = l.thread_id
LEFT JOIN subscriptions s ON s.subscription_id = (
    SELECT s2.subscription_id FROM subscriptions s2
    WHERE s2.customer_id = l.customer_id
      AND s2.start_day <= COALESCE(fs.day, l.day)
    ORDER BY s2.start_day DESC, s2.subscription_id DESC LIMIT 1
)
WHERE l.thread_type = '{thread_type}'
  AND l.thread_id BETWEEN {low} AND {high}
ORDER BY l.thread_id
"""


def outcome(row):
    reason = row["close_reason"] or "open"
    if reason == "accepted":
        return "accepted"
    if reason in ("timeout", "involuntary", "lead_expired"):
        return reason
    return "open"


def bucket_key(record):
    return (record["group_id"], record["outcome"])


rows = []
for thread_type in ("churn_prevention", "new_lead"):
    bounds = nm.query(
        "SELECT MIN(thread_id) AS low, MAX(thread_id) AS high "
        f"FROM enterprise_turns WHERE thread_type='{thread_type}'"
    )["rows"][0]
    if bounds["low"] is None:
        continue
    low = int(bounds["low"])
    high = int(bounds["high"])
    for start in range(low, high + 1, 500):
        rows.extend(nm.query(QUERY.format(
            thread_type=thread_type,
            low=start,
            high=min(start + 499, high)))["rows"])
records = []
for row in rows:
    record = dict(row)
    record["outcome"] = outcome(row)
    offers = json.loads(row["offer_json"] or "[]")
    record["offers"] = offers
    if isinstance(offers, list) and offers and isinstance(offers[0], dict):
        record["offer_plan"] = offers[0].get("plan")
        record["offer_price"] = float(offers[0].get("price_per_seat") or 0.0)
        record["offer_prices"] = {
            offer.get("plan"): float(offer.get("price_per_seat") or 0.0)
            for offer in offers if isinstance(offer, dict)
        }
        if row["prior_price"]:
            record["offer_ratio"] = record["offer_price"] / float(row["prior_price"])
    records.append(record)

for thread_type in ("churn_prevention", "new_lead"):
    subset = [r for r in records if r["thread_type"] == thread_type]
    print(f"\n=== {thread_type}: {len(subset)} threads ===")

    groups = sorted({r["group_id"] for r in subset})
    for group in groups:
        group_rows = [r for r in subset if r["group_id"] == group]
        counts = {}
        for r in group_rows:
            counts[r["outcome"]] = counts.get(r["outcome"], 0) + 1
        accepted = [r for r in group_rows if r["outcome"] == "accepted"]
        ratios = [r.get("offer_ratio") for r in accepted if r.get("offer_ratio")]
        print(json.dumps({
            "group": group,
            "counts": counts,
            "accepted_median_discount": round(1 - statistics.median(ratios), 3)
            if ratios else None,
            "accepted_mean_discount": round(1 - statistics.mean(ratios), 3)
            if ratios else None,
        }, sort_keys=True))

    if thread_type == "churn_prevention":
        print("\nDiscount bands, all groups:")
        bands = [(0.0, 0.1), (0.1, 0.2), (0.2, 0.3), (0.3, 0.4),
                 (0.4, 0.5), (0.5, 0.7), (0.7, 1.1)]
        for low, high in bands:
            band_rows = [
                r for r in subset
                if r.get("offer_ratio") is not None
                and low <= 1 - r["offer_ratio"] < high
            ]
            counts = {}
            for r in band_rows:
                counts[r["outcome"]] = counts.get(r["outcome"], 0) + 1
            if band_rows:
                print(json.dumps({
                    "discount_low": low,
                    "discount_high": high,
                    "n": len(band_rows),
                    "counts": counts,
                    "accept_rate": round(
                        counts.get("accepted", 0) / len(band_rows), 3),
                }, sort_keys=True))

        print("\nSingle-plan retention ratio distribution by outcome:")
        for group in groups:
            for outcome_name in ("accepted", "timeout", "open"):
                ratios = sorted(
                    r["offer_ratio"] for r in subset
                    if r["group_id"] == group
                    and r["outcome"] == outcome_name
                    and r.get("offer_ratio") is not None
                    and len(r.get("offers", [])) == 1
                )
                if not ratios:
                    continue
                def quantile(frac):
                    return ratios[min(len(ratios) - 1, int(frac * len(ratios)))]
                print(json.dumps({
                    "group": group,
                    "outcome": outcome_name,
                    "n": len(ratios),
                    "ratio_p10": round(quantile(0.1), 3),
                    "ratio_median": round(quantile(0.5), 3),
                    "ratio_p90": round(quantile(0.9), 3),
                }, sort_keys=True))

    if thread_type == "new_lead":
        print("\nB-offer demand by group and rounded price:")
        for group in groups:
            prices = {}
            for r in subset:
                if r["group_id"] != group:
                    continue
                price = r.get("offer_prices", {}).get("B")
                if price is None or r["outcome"] == "open":
                    continue
                key = round(price, 2)
                bucket = prices.setdefault(key, {"accepted": 0, "timeout": 0})
                bucket[r["outcome"]] = bucket.get(r["outcome"], 0) + 1
            for price, counts in sorted(prices.items()):
                completed = counts["accepted"] + counts["timeout"]
                if completed:
                    print(json.dumps({
                        "group": group,
                        "b_price": price,
                        "n": completed,
                        "accepted": counts["accepted"],
                        "accept_rate": round(counts["accepted"] / completed, 3),
                    }, sort_keys=True))

