projs=nm.query(\\\"SELECT project_id,tier,started_day,expected_quality_boost,quality_boost_applied FROM research_projects WHERE status='completed'\\\")['rows']
ns={r['message']:r['day'] for r in nm.query(\\\"SELECT day,message FROM notifications WHERE type='research_complete'\\\")['rows']}
by={}
for p in projs:
 d=ns.get('R&D complete: '+p['project_id'])
 if d is None: continue
 by.setdefault(p['tier'],[]).append((d-p['started_day'],p['quality_boost_applied']))
for tier,vals in sorted(by.items()):
 ds=[x[0] for x in vals]; qs=[x[1] for x in vals]; ds2=sorted(ds)
