def offer_for(row):
    group_id = row["group_id"]
    match = COUNTER_RE.search(row.get("message_text") or "")
    if match:
        plan = match.group("plan")
        requested = float(match.group("price"))
        floor = offer_cost_floor(row, plan)
        if row["thread_type"] == "renegotiation" and row["current_price"]:
            floor = max(floor, float(row["current_price"]))
        target = max(requested, floor)
        return {
            "kind": "accept_counter" if requested >= floor else "counter_floor",
            "deal": [row["customer_id"], [[plan, round(target, 4)]]],
            "target": target,
            "cost_floor": floor,
        }

    if row["thread_type"] == "churn_prevention":
        plan = row["current_plan"] or "C"
        current = float(row["current_price"] or 0.0)
        factor = RETENTION_FACTOR.get(group_id, DEFAULT_RETENTION_FACTOR)
        floor = offer_cost_floor(row, plan)
        target = max(current * factor, floor)
        return {
            "kind": f"retain_{int(round(factor * 100))}pct_of_current",
            "deal": [row["customer_id"], [[plan, round(target, 4)]]],
            "target": target,
            "cost_floor": floor,
