        floor = (actual_floor * COST_MULTIPLIER
                 if actual_floor is not None
                 else cost_floor(group_id, plan))
        offers.append([plan, round(max(ladder_price, floor), 4)])
    return {
        "kind": "lead_ladder",
        "deal": [row["customer_id"], offers],
        "target": None,
        "cost_floor": None,
    }


